import json

try:
    with open('network.json', 'r') as f:
        data = json.load(f)

    print("Keys:", data.keys())

    if 'bus' in data:
        print("\nFirst bus:", data['bus'][0])
        print("Bus columns likely: bus_i, type, Pd, Qd, Gs, Bs, area, Vm, Va, baseKV, zone, Vmax, Vmin")

    if 'gen' in data:
        print("\nFirst gen:", data['gen'][0])
        print("Gen columns likely: bus, Pg, Qg, Qmax, Qmin, Vg, mBase, status, Pmax, Pmin, Pc1, Pc2, Qc1min, Qc1max, Qc2min, Qc2max, ramp_agc, ramp_10, ramp_30, ramp_q, apf")

    if 'branch' in data:
        print("\nFirst branch:", data['branch'][0])
        print("Branch columns likely: fbus, tbus, r, x, b, rateA, rateB, rateC, ratio, angle, status, angmin, angmax")

    if 'gencost' in data:
        print("\nFirst gencost:", data['gencost'][0])

except Exception as e:
    print(e)

